# Checks the proof steps: group <s1,s2,t3> has order 24 and equals S; q_i and H_i facts; generators invariant on all triples; X_i(phi psi_pi) = X_pi(i)(phi) for all 120 permutations.
# Run from this directory: python3 uniformity_proof_check.py   (needs numpy)
exec(open('sym_probe.py').read().split("fam={")[0])
import numpy as np, itertools, random
# 1. group generated by s1,s2,t3 (acting on triples as 3x3 over F2; rows over (x,y,z) with bits 4,2,1)
def row(s): return sum(1<<(2-'xyz'.index(c)) for c in s)
def mat(*rows): return tuple(row(r) for r in rows)
s1=mat('x','xy','z'); s2=mat('x','yz','z'); t3=mat('xy','y','yz')
def comp(A,B):  # (A after B): substitute: new = A applied to B-image rows ; represent via action on symbolic triple
    # apply A to triple whose components are B's rows
    out=[]
    for r in A:
        o=0
        for k in range(3):
            if r>>(2-k)&1: o^=B[k]
        out.append(o)
    return tuple(out)
I=mat('x','y','z'); G={I}; fr=[I]
while fr:
    nf=[]
    for g in fr:
        for h in (s1,s2,t3):
            for n in (comp(g,h),comp(h,g)):
                if n not in G: G.add(n); nf.append(n)
    fr=nf
S={M for M in GL if (M[0]^M[2])==row('xz')}
print('order of <s1,s2,t3> =',len(G),'; |{M: row1+row3 = x+z}| =',len(S),'; equal:',G==S)
# 2. frame automorphisms: q_i = coefficient vectors in (a,b,c,d) bits 8,4,2,1
def v(s): return sum(1<<(3-'abcd'.index(c)) for c in s)
q=[v('ac'),v('ad'),v('bd'),v('acd'),v('abd')]
Trows=[[v('a'),v('b'),v('c')],[v('a'),v('bc'),v('d')],[v('b'),v('c'),v('d')],[v('a'),v('b'),v('cd')],[v('ab'),v('c'),v('d')]]
def span(vs):
    S_={0}
    for x in vs: S_|={y^x for y in S_}
    return frozenset(S_)
H=[span(r) for r in Trows]
print('q_i = first+third of T_i:',all(Trows[i][0]^Trows[i][2]==q[i] for i in range(5)),' q_i in H_i:',all(q[i] in H[i] for i in range(5)),' q_j in H_i (i!=j):',any(q[j] in H[i] for i in range(5) for j in range(5) if i!=j))
def psi_for(pi):
    # linear map on F2^4 (as function) with psi(q_i)=q_pi(i); define by basis q_0..q_3
    basis=q[:4]; img=[q[pi[i]] for i in range(4)]
    table={}
    for m in range(16):
        x=0;y=0
        for k in range(4):
            if m>>k&1: x^=basis[k]; y^=img[k]
        table[x]=y
    assert len(table)==16
    return table
trip=[(x,y,z) for x in range(N) for y in range(N) for z in range(N)]
# 3. test exchangeability map on a random sigma from the left+right family
random.seed(9)
cons=[alpha_lin(x,x,z) for x in rng for z in rng]+[alpha_lin(x,z,z) for x in rng for z in rng]
basis=solve(cons)
for trial in range(2):
    X=1-2*alpha_arr(sample(basis))
    # generators invariant on ALL triples?
    gens_ok=all(X[t]==X[apply(M,t)] for M in (s1,s2,t3) for t in trip)
    allq=list(itertools.product(range(16),repeat=4))
    # evaluate X_i for all quadruples, and the transformed quadruple phi psi
    bad=0
    for pi in itertools.permutations(range(5)):
        psi=psi_for(pi) if True else None
        # psi defined on coefficient space via q_0..q_3 -> q_pi(0..3); need psi(q_4)=q_pi(4) automatically
        assert psi[q[4]]==q[pi[4]]
        e=[8,4,2,1]  # coefficient basis a,b,c,d
        cols=[psi[x] for x in e]   # psi(e_k) as coefficient vectors
        # new quadruple a'_k = sum_m (cols[k] bit m) * phi_m
        for phi in random.sample(allq,300):
            new=[]
            for k in range(4):
                o=0
                for m in range(4):
                    if cols[k]>>(3-m)&1: o^=phi[m]
                new.append(o)
            a,b,c,d=phi; a2,b2,c2,d2=new
            Told=[(a,b,c),(a,b^c,d),(b,c,d),(a,b,c^d),(a^b,c,d)]
            Tnew=[(a2,b2,c2),(a2,b2^c2,d2),(b2,c2,d2),(a2,b2,c2^d2),(a2^b2,c2,d2)]
            for i in range(5):
                if X[Tnew[i]]!=X[Told[pi[i]]]: bad+=1
    print('trial',trial,'generators invariant on all triples:',gens_ok,' mismatches over 120 perms x 300 random quadruples x 5 edges:',bad)
